// Kazdy kontekst - osobny pakiet, osobny, niezalezny model tego samego pojecia
record CatalogProduct(String sku, String displayName, String marketingDescription, String category) {}

record WarehouseStockItem(String sku, double weightKg, String shelfLocation, int quantityOnHand) {}

record BillingInvoiceLineItem(String sku, double netPrice, double vatRate, String taxCode) {}

// Zaden z tych typow NIE jest "tym samym Product" wspoldzielonym miedzy kontekstami

// Lokalny widok Katalogu - zna TYLKO to, czego Katalog potrzebuje
record CatalogAvailabilityView(String sku, boolean inStock) {}

class WarehouseToCatalogTranslator {
    CatalogAvailabilityView translate(WarehouseStockItem item) {
        // Katalog NIE zna pol weightKg/shelfLocation - to szczegoly wylacznie Magazynu
        return new CatalogAvailabilityView(item.sku(), item.quantityOnHand() > 0);
    }
}

// ZLE: 1 klasa "dla wszystkich" - kazdy kontekst dodaje swoje pola do wspolnego worka
class ProductGodClass {
    String sku;
    String displayName;            // potrzebne tylko Katalogowi
    String marketingDescription;   // potrzebne tylko Katalogowi
    double weightKg;               // potrzebne tylko Magazynowi
    String shelfLocation;          // potrzebne tylko Magazynowi
    double netPrice;               // potrzebne tylko Fakturowaniu
    double vatRate;                // potrzebne tylko Fakturowaniu
    // kazdy zespol dopisuje kolejne pola - klasa rosnie w nieskonczonosc
}

